import pytest

from docket import validate_einvoice

pytest.importorskip("lxml")
pytest.importorskip("saxonche")


@pytest.mark.parametrize(
    "doctype",
    [
        '<!DOCTYPE Invoice [<!ENTITY xxe SYSTEM "file:///etc/passwd">]>',
        '<!DOCTYPE Invoice [<!ENTITY a "1234567890"><!ENTITY b "&a;&a;&a;&a;&a;&a;&a;&a;&a;&a;">]>',
    ],
)
def test_dtd_external_entities_and_expansion_are_refused(doctype):
    xml = (
        doctype
        + '<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2">&xxe;</Invoice>'
    ).replace("&xxe;", "&b;" if "ENTITY b" in doctype else "&xxe;")
    result = validate_einvoice(xml.encode())
    assert not result.valid
    assert {issue.code for issue in result.issues} == {"DOCKET-XML"}
    assert "root:" not in result.model_dump_json()

from __future__ import annotations

import inspect
import json
from pathlib import Path

import pytest

import docket
from docket import (
    DocumentError,
    DocumentResult,
    OcrOptions,
    ProcessingMetrics,
    ProcessOptions,
    ReviewOptions,
)
from docket._deprecation import warn_deprecated

SNAPSHOT = Path(__file__).parent / "snapshots" / "public_api.json"
KEY_FUNCTIONS = (
    "export_document",
    "get_ocr_backend",
    "get_schema",
    "list_exporters",
    "list_ocr_backends",
    "list_schemas",
    "process_batch",
    "process_document",
    "register_exporter",
    "register_ocr_backend",
    "register_schema",
    "validate_einvoice",
)
KEY_MODELS = (
    OcrOptions,
    ReviewOptions,
    ProcessOptions,
    DocumentError,
    ProcessingMetrics,
    DocumentResult,
)


def _annotation_name(annotation: object) -> str:
    text = str(annotation)
    for prefix in ("<class '", "<enum '"):
        if text.startswith(prefix) and text.endswith("'>"):
            return text[len(prefix):-2]
    return text


def _contract() -> dict[str, object]:
    return {
        "names": sorted(docket.__all__),
        "functions": {
            name: str(inspect.signature(getattr(docket, name)))
            for name in KEY_FUNCTIONS
        },
        "models": {
            model.__name__: {
                name: {
                    "annotation": _annotation_name(field.annotation),
                    "required": field.is_required(),
                }
                for name, field in model.model_fields.items()
            }
            for model in KEY_MODELS
        },
    }


def test_public_api_matches_snapshot():
    expected = json.loads(SNAPSHOT.read_text())
    assert _contract() == expected


def test_all_contains_only_bound_names():
    assert not [name for name in docket.__all__ if not hasattr(docket, name)]


def test_deprecation_warning_points_to_caller():
    with pytest.warns(
        DeprecationWarning,
        match=r"old_api is deprecated; use new_api instead; it will be removed in 0\.5",
    ) as caught:
        warn_deprecated("old_api", replacement="new_api", removal="0.5")

    assert caught[0].filename == __file__

"""The UI's model pickers write straight back to `config`, which only works
because every call site resolves the model at call time. That's an easy
thing to break with a well-meant refactor (binding the default in a
function signature would do it silently), so it's pinned here.
"""
from docket import config, llm_client


class _FakeResponse:
    status_code = 200

    def raise_for_status(self) -> None:
        pass

    def json(self) -> dict:
        return {"message": {"content": "{}"}}


def _capture_payload(monkeypatch) -> dict:
    captured: dict = {}

    def fake_post(url, json=None, headers=None, timeout=None):
        captured.update(json)
        return _FakeResponse()

    monkeypatch.setattr(llm_client.httpx, "post", fake_post)
    return captured


def test_config_model_is_resolved_at_call_time(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "TEXT_MODEL", "picked-in-the-ui:v9")

    llm_client.chat_json("hi")
    assert captured["model"] == "picked-in-the-ui:v9"


def test_explicit_backend_model_wins_over_config(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "TEXT_MODEL", "from-config:v1")

    with llm_client.use_backend(llm_client.OllamaBackend(text_model="explicit:v2")):
        llm_client.chat_json("hi")
    assert captured["model"] == "explicit:v2"


def test_thinking_flag_is_sent(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "ENABLE_THINKING", False)

    llm_client.chat_json("hi")
    assert captured["think"] is False


def test_json_schema_is_sent_to_ollama_when_provided(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "TEXT_MODEL", "local-model:latest")
    schema = {"type": "object", "properties": {"answer": {"type": "string"}}}
    llm_client.chat_json("hi", schema=schema)
    assert captured["format"] == schema


def test_cloud_uses_json_mode_instead_of_unsupported_schema(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "TEXT_MODEL", "example:cloud")
    llm_client.chat_json("synthetic", schema={"type": "object"})
    assert captured["format"] == "json"


def test_cloud_fenced_json_is_parsed(monkeypatch):
    class Response(_FakeResponse):
        def json(self):
            return {"message": {"content": '```json\n{"total_amount": 10}\n```'}}

    monkeypatch.setattr(llm_client.httpx, "post", lambda *args, **kwargs: Response())
    monkeypatch.setattr(config, "TEXT_MODEL", "example:cloud")
    assert llm_client.chat_json("synthetic") == {
        "total_amount": 10
    }


def _fake_tags(models: list[dict]):
    class Resp:
        def raise_for_status(self) -> None:
            pass

        def json(self) -> dict:
            return {"models": models}

    return lambda url, timeout=None: Resp()


MODELS = [
    {"name": "chat-only:v1", "capabilities": ["completion", "tools"]},
    {"name": "sees-things:v1", "capabilities": ["completion", "vision"]},
    {"name": "embeddings-only:v1", "capabilities": ["embedding"]},
    {"name": "no-capabilities-reported:v1"},
]


def test_embedding_models_are_not_offered(monkeypatch):
    monkeypatch.setattr(llm_client.httpx, "get", _fake_tags(MODELS))
    assert llm_client.list_models() == ["chat-only:v1", "sees-things:v1"]


def test_vision_list_requires_both_capabilities(monkeypatch):
    monkeypatch.setattr(llm_client.httpx, "get", _fake_tags(MODELS))
    assert llm_client.list_models(vision_only=True) == ["sees-things:v1"]


def test_unreachable_ollama_returns_no_choices_rather_than_raising(monkeypatch):
    def boom(url, timeout=None):
        raise llm_client.httpx.ConnectError("connection refused")

    monkeypatch.setattr(llm_client.httpx, "get", boom)
    assert llm_client.list_models() == []


def test_a_document_run_uses_the_selected_vision_model(monkeypatch):
    captured = _capture_payload(monkeypatch)
    monkeypatch.setattr(config, "VISION_MODEL", "picked-vision:v9")
    llm_client.vision_transcribe(b"img")
    assert captured["model"] == "picked-vision:v9"
